mapper.update:
UPDATE stock_watch_alert_delivery_obligation
SET open_episode_key=NULL, row_version=row_version+1
WHERE open_episode_key=#{openEpisodeKey}
  AND episode_suppressed_until IS NOT NULL
  AND episode_suppressed_until <= #{now}

mapper.select:
SELECT COUNT(*) FROM stock_watch_alert_delivery_obligation
WHERE rule_id=#{ruleId} AND symbol=#{symbol} AND market=#{market}
  AND signal_fingerprint=#{signalFingerprint}
  AND initial_status='SENT' AND episode_suppressed_until > #{now}
